contracts/ArcFlowPay.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";

/**
 * @title ArcFlowPay - Merchant Payment System
 * @notice Merchants register, users pay with USDC via QR/address
 * @dev Instant settlement, 0.5% merchant fee
 */
contract ArcFlowPay {
    address public owner;
    IERC20 public usdc;

    struct Merchant {
        address wallet;
        string name;
        string category;
        bool active;
        uint256 totalReceived;
        uint256 txCount;
    }

    mapping(address => Merchant) public merchants;
    address[] public merchantList;

    // Fee: 0.5% paid by merchant on each payment
    uint256 public feeBps = 50;
    address public feeCollector;

    event MerchantRegistered(address indexed merchant, string name);
    event Payment(address indexed from, address indexed merchant, uint256 amount, uint256 fee);
    event MerchantDeactivated(address indexed merchant);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyMerchant() {
        require(merchants[msg.sender].active, "Not active merchant");
        _;
    }

    constructor(address _usdc, address _feeCollector) {
        owner = msg.sender;
        usdc = IERC20(_usdc);
        feeCollector = _feeCollector;
    }

    // ========== Merchant Registration ==========
    function registerMerchant(string calldata name, string calldata category) external {
        require(!merchants[msg.sender].active, "Already registered");
        require(bytes(name).length > 0, "Empty name");

        merchants[msg.sender] = Merchant({
            wallet: msg.sender,
            name: name,
            category: category,
            active: true,
            totalReceived: 0,
            txCount: 0
        });

        merchantList.push(msg.sender);
        emit MerchantRegistered(msg.sender, name);
    }

    function deactivateMerchant(address merchant) external {
        require(msg.sender == owner || msg.sender == merchant, "Not authorized");
        merchants[merchant].active = false;
        emit MerchantDeactivated(merchant);
    }

    // ========== Payment ==========
    function pay(address merchant, uint256 amount) external {
        require(amount > 0, "Zero amount");
        require(merchants[merchant].active, "Merchant not active");

        uint256 fee = (amount * feeBps) / 10000;
        uint256 netAmount = amount - fee;

        // Transfer to merchant
        require(usdc.transferFrom(msg.sender, merchant, netAmount), "Transfer failed");

        // Collect fee
        if (fee > 0) {
            require(usdc.transferFrom(msg.sender, feeCollector, fee), "Fee failed");
        }

        merchants[merchant].totalReceived += netAmount;
        merchants[merchant].txCount++;

        emit Payment(msg.sender, merchant, amount, fee);
    }

    // ========== View ==========
    function getMerchant(address wallet) external view returns (string memory name, string memory category, bool active, uint256 totalReceived, uint256 txCount) {
        Merchant storage m = merchants[wallet];
        return (m.name, m.category, m.active, m.totalReceived, m.txCount);
    }

    function getMerchantCount() external view returns (uint256) {
        return merchantList.length;
    }

    // ========== Admin ==========
    function setFee(uint256 _feeBps) external onlyOwner {
        require(_feeBps <= 500, "Too high");
        feeBps = _feeBps;
    }
}

contracts/ArcFlowRecurring.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";

/**
 * @title ArcFlowRecurring - Automated Recurring Payments
 * @notice Schedule recurring USDC payments (subscriptions, rent, salary)
 * @dev Anyone can execute due payments (keeper pattern)
 */
contract ArcFlowRecurring {
    address public owner;
    IERC20 public usdc;

    enum Frequency { Weekly, Monthly, Quarterly, Yearly }

    struct RecurringPayment {
        address payer;
        address payee;
        uint256 amount;
        Frequency frequency;
        uint256 startTime;
        uint256 nextPayment;
        uint256 totalPaid;
        uint8 maxExecutions; // 0 = unlimited
        uint8 executions;
        bool active;
        string name;
    }

    RecurringPayment[] public payments;
    mapping(address => uint256[]) public userPayments;

    event RecurringCreated(uint256 indexed paymentId, address indexed payer, address indexed payee, uint256 amount);
    event RecurringExecuted(uint256 indexed paymentId, address indexed payer, address indexed payee, uint256 amount);
    event RecurringCancelled(uint256 indexed paymentId);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor(address _usdc) {
        owner = msg.sender;
        usdc = IERC20(_usdc);
    }

    // ========== Create Recurring ==========
    function createRecurring(
        address payee,
        uint256 amount,
        Frequency frequency,
        uint8 maxExecutions,
        string calldata name
    ) external returns (uint256 paymentId) {
        require(payee != address(0), "Zero address");
        require(amount > 0, "Zero amount");
        require(payee != msg.sender, "Self payment");

        paymentId = payments.length;

        uint256 interval = _getInterval(frequency);

        payments.push(RecurringPayment({
            payer: msg.sender,
            payee: payee,
            amount: amount,
            frequency: frequency,
            startTime: block.timestamp,
            nextPayment: block.timestamp + interval,
            totalPaid: 0,
            maxExecutions: maxExecutions,
            executions: 0,
            active: true,
            name: name
        }));

        userPayments[msg.sender].push(paymentId);

        emit RecurringCreated(paymentId, msg.sender, payee, amount);
    }

    // ========== Execute Payment (anyone can call - keeper pattern) ==========
    function executePayment(uint256 paymentId) external {
        RecurringPayment storage p = payments[paymentId];
        require(p.active, "Not active");
        require(block.timestamp >= p.nextPayment, "Not due yet");
        require(p.maxExecutions == 0 || p.executions < p.maxExecutions, "Max reached");

        // Transfer from payer to payee
        require(usdc.transferFrom(p.payer, p.payee, p.amount), "Transfer failed");

        p.executions++;
        p.totalPaid += p.amount;
        p.nextPayment = block.timestamp + _getInterval(p.frequency);

        // Auto-deactivate if max reached
        if (p.maxExecutions > 0 && p.executions >= p.maxExecutions) {
            p.active = false;
        }

        emit RecurringExecuted(paymentId, p.payer, p.payee, p.amount);
    }

    // ========== Cancel ==========
    function cancelRecurring(uint256 paymentId) external {
        RecurringPayment storage p = payments[paymentId];
        require(msg.sender == p.payer || msg.sender == owner, "Not authorized");
        require(p.active, "Already cancelled");

        p.active = false;
        emit RecurringCancelled(paymentId);
    }

    // ========== View ==========
    function getPayment(uint256 paymentId) external view returns (
        address payer, address payee, uint256 amount, Frequency frequency,
        uint256 nextPayment, uint256 totalPaid, uint8 executions, bool active, string memory name
    ) {
        RecurringPayment storage p = payments[paymentId];
        return (p.payer, p.payee, p.amount, p.frequency, p.nextPayment, p.totalPaid, p.executions, p.active, p.name);
    }

    function getUserPayments(address user) external view returns (uint256[] memory) {
        return userPayments[user];
    }

    function getPaymentCount() external view returns (uint256) {
        return payments.length;
    }

    function isDue(uint256 paymentId) external view returns (bool) {
        RecurringPayment storage p = payments[paymentId];
        return p.active && block.timestamp >= p.nextPayment;
    }

    // ========== Internal ==========
    function _getInterval(Frequency f) internal pure returns (uint256) {
        if (f == Frequency.Weekly) return 7 days;
        if (f == Frequency.Monthly) return 30 days;
        if (f == Frequency.Quarterly) return 90 days;
        return 365 days; // Yearly
    }
}

contracts/ArcFlowSend.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";

/**
 * @title ArcFlowSend - Gasless USDC Transfers
 * @notice Relayer submits tx on behalf of user, user signs off-chain
 * @dev Uses EIP-712 meta-transactions for gasless sends
 */
contract ArcFlowSend {
    address public owner;
    IERC20 public usdc;

    // Relayer whitelist
    mapping(address => bool) public relayers;

    // Nonce per user to prevent replay
    mapping(address => uint256) public nonces;

    // Fee: 0.1% of transfer amount (basis points)
    uint256 public feeBps = 10; // 10 bps = 0.1%
    address public feeCollector;

    // Min transfer: $1 USDC
    uint256 public minTransfer = 1_000_000; // 6 decimals

    // Struct for meta-tx
    struct SendRequest {
        address from;
        address to;
        uint256 amount;
        uint256 nonce;
        uint256 deadline;
    }

    bytes32 public constant SEND_TYPEHASH = keccak256(
        "SendRequest(address from,address to,uint256 amount,uint256 nonce,uint256 deadline)"
    );

    event Sent(address indexed from, address indexed to, uint256 amount, uint256 fee);
    event RelayerUpdated(address indexed relayer, bool status);
    event FeeUpdated(uint256 newFeeBps);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyRelayer() {
        require(relayers[msg.sender], "Not relayer");
        _;
    }

    constructor(address _usdc, address _feeCollector) {
        owner = msg.sender;
        usdc = IERC20(_usdc);
        feeCollector = _feeCollector;
    }

    // ========== Gasless Send via Meta-Tx ==========
    function sendWithSig(
        SendRequest calldata req,
        bytes calldata signature
    ) external onlyRelayer {
        require(block.timestamp <= req.deadline, "Expired");
        require(req.nonce == nonces[req.from], "Invalid nonce");
        require(req.amount >= minTransfer, "Below minimum");

        // Verify EIP-712 signature
        bytes32 structHash = keccak256(abi.encode(
            SEND_TYPEHASH,
            req.from,
            req.to,
            req.amount,
            req.nonce,
            req.deadline
        ));
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", _domainSeparator(), structHash));
        address signer = _recoverSigner(digest, signature);
        require(signer == req.from, "Invalid signature");

        nonces[req.from]++;

        uint256 fee = (req.amount * feeBps) / 10000;
        uint256 netAmount = req.amount - fee;

        // Transfer from user to recipient
        require(usdc.transferFrom(req.from, req.to, netAmount), "Transfer failed");

        // Collect fee
        if (fee > 0) {
            require(usdc.transferFrom(req.from, feeCollector, fee), "Fee transfer failed");
        }

        emit Sent(req.from, req.to, netAmount, fee);
    }

    // ========== Direct Send (user pays gas) ==========
    function send(address to, uint256 amount) external {
        require(amount >= minTransfer, "Below minimum");

        uint256 fee = (amount * feeBps) / 10000;
        uint256 netAmount = amount - fee;

        require(usdc.transferFrom(msg.sender, to, netAmount), "Transfer failed");

        if (fee > 0) {
            require(usdc.transferFrom(msg.sender, feeCollector, fee), "Fee transfer failed");
        }

        emit Sent(msg.sender, to, netAmount, fee);
    }

    // ========== Admin ==========
    function setRelayer(address relayer, bool status) external onlyOwner {
        relayers[relayer] = status;
        emit RelayerUpdated(relayer, status);
    }

    function setFee(uint256 _feeBps) external onlyOwner {
        require(_feeBps <= 500, "Fee too high"); // Max 5%
        feeBps = _feeBps;
        emit FeeUpdated(_feeBps);
    }

    function setFeeCollector(address _collector) external onlyOwner {
        feeCollector = _collector;
    }

    function withdraw() external onlyOwner {
        uint256 balance = usdc.balanceOf(address(this));
        require(balance > 0, "Nothing to withdraw");
        require(usdc.transfer(owner, balance), "Withdraw failed");
    }

    // ========== Helpers ==========
    function getNonce(address user) external view returns (uint256) {
        return nonces[user];
    }

    function _domainSeparator() internal view returns (bytes32) {
        return keccak256(abi.encode(
            keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
            keccak256("ArcFlowSend"),
            keccak256("1"),
            block.chainid,
            address(this)
        ));
    }

    function _recoverSigner(bytes32 digest, bytes calldata signature) internal pure returns (address) {
        require(signature.length == 65, "Invalid sig length");
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := calldataload(signature.offset)
            s := calldataload(add(signature.offset, 32))
            v := byte(0, calldataload(add(signature.offset, 64)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "Invalid v");
        return ecrecover(digest, v, r, s);
    }
}

contracts/ArcFlowSplit.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";

/**
 * @title ArcFlowSplit - Bill Splitting Contract
 * @notice Split expenses among friends, track who paid and who owes
 * @dev Group-based bill splitting with settlement
 */
contract ArcFlowSplit {
    address public owner;
    IERC20 public usdc;

    enum SplitStatus { Active, Partial, Settled }

    struct SplitGroup {
        address creator;
        string name;
        uint256 totalAmount;
        uint256 memberCount;
        uint256 settledCount;
        SplitStatus status;
        uint256 createdAt;
    }

    struct Member {
        address wallet;
        uint256 share; // Amount owed (in USDC units)
        bool paid;
        uint256 paidAt;
    }

    SplitGroup[] public groups;
    mapping(uint256 => Member[]) public groupMembers; // groupId => members
    mapping(uint256 => mapping(address => bool)) public isMember;

    event GroupCreated(uint256 indexed groupId, address indexed creator, string name, uint256 totalAmount);
    event MemberAdded(uint256 indexed groupId, address indexed member, uint256 share);
    event Settled(uint256 indexed groupId, address indexed member, uint256 amount);
    event GroupSettled(uint256 indexed groupId);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor(address _usdc) {
        owner = msg.sender;
        usdc = IERC20(_usdc);
    }

    // ========== Create Split ==========
    function createSplit(
        string calldata name,
        address[] calldata members,
        uint256[] calldata shares,
        address recipient
    ) external returns (uint256 groupId) {
        require(members.length == shares.length, "Length mismatch");
        require(members.length > 0, "No members");
        require(members.length <= 50, "Too many members");

        uint256 totalAmount = 0;
        for (uint256 i = 0; i < shares.length; i++) {
            require(shares[i] > 0, "Zero share");
            totalAmount += shares[i];
            require(!isMember[groups.length][members[i]], "Duplicate member");
        }

        groupId = groups.length;

        groups.push(SplitGroup({
            creator: msg.sender,
            name: name,
            totalAmount: totalAmount,
            memberCount: members.length,
            settledCount: 0,
            status: SplitStatus.Active,
            createdAt: block.timestamp
        }));

        for (uint256 i = 0; i < members.length; i++) {
            groupMembers[groupId].push(Member({
                wallet: members[i],
                share: shares[i],
                paid: false,
                paidAt: 0
            }));
            isMember[groupId][members[i]] = true;
            emit MemberAdded(groupId, members[i], shares[i]);
        }

        emit GroupCreated(groupId, msg.sender, name, totalAmount);
    }

    // ========== Settle Share ==========
    function settleShare(uint256 groupId, address recipient) external {
        SplitGroup storage group = groups[groupId];
        require(group.status != SplitStatus.Settled, "Already settled");
        require(isMember[groupId][msg.sender], "Not a member");

        Member[] storage members = groupMembers[groupId];
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i].wallet == msg.sender) {
                require(!members[i].paid, "Already paid");

                // Transfer share to recipient
                require(usdc.transferFrom(msg.sender, recipient, members[i].share), "Transfer failed");

                members[i].paid = true;
                members[i].paidAt = block.timestamp;
                group.settledCount++;

                // Update status
                if (group.settledCount == group.memberCount) {
                    group.status = SplitStatus.Settled;
                    emit GroupSettled(groupId);
                } else {
                    group.status = SplitStatus.Partial;
                }

                emit Settled(groupId, msg.sender, members[i].share);
                return;
            }
        }
    }

    // ========== View ==========
    function getGroup(uint256 groupId) external view returns (
        address creator, string memory name, uint256 totalAmount,
        uint256 memberCount, uint256 settledCount, SplitStatus status
    ) {
        SplitGroup storage g = groups[groupId];
        return (g.creator, g.name, g.totalAmount, g.memberCount, g.settledCount, g.status);
    }

    function getGroupMembers(uint256 groupId) external view returns (
        address[] memory wallets, uint256[] memory shares, bool[] memory paid
    ) {
        Member[] storage members = groupMembers[groupId];
        uint256 len = members.length;
        wallets = new address[](len);
        shares = new uint256[](len);
        paid = new bool[](len);

        for (uint256 i = 0; i < len; i++) {
            wallets[i] = members[i].wallet;
            shares[i] = members[i].share;
            paid[i] = members[i].paid;
        }
    }

    function getUserGroups(address user) external view returns (uint256[] memory) {
        uint256 count = 0;
        for (uint256 i = 0; i < groups.length; i++) {
            if (isMember[i][user]) count++;
        }

        uint256[] memory result = new uint256[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < groups.length; i++) {
            if (isMember[i][user]) {
                result[idx] = i;
                idx++;
            }
        }
        return result;
    }

    function getGroupCount() external view returns (uint256) {
        return groups.length;
    }
}

contracts/ArcFlowSwap.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interfaces/IERC20.sol";

/**
 * @title ArcFlowSwap - Stablecoin AMM
 * @notice Constant-product AMM optimized for stablecoin swaps (low slippage)
 * @dev Supports USDC/USDT/DAI/EURC pairs with 0.3% fee
 */
contract ArcFlowSwap {
    address public owner;

    // Fee: 0.3% (30 basis points)
    uint256 public constant FEE_BPS = 30;
    uint256 public constant FEE_DENOMINATOR = 10000;

    // Pool: keccak(tokenA, tokenB) => Pool
    struct Pool {
        uint256 reserveA;
        uint256 reserveB;
        uint256 totalLP;
        bool exists;
    }

    mapping(bytes32 => Pool) public pools;
    mapping(bytes32 => mapping(address => uint256)) public lpBalances;

    // Whitelisted tokens (only stablecoins)
    mapping(address => bool) public whitelisted;

    event Swap(address indexed user, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);
    event LiquidityAdded(address indexed provider, bytes32 poolId, uint256 amountA, uint256 amountB, uint256 lpTokens);
    event LiquidityRemoved(address indexed provider, bytes32 poolId, uint256 amountA, uint256 amountB);
    event PoolCreated(bytes32 poolId, address tokenA, address tokenB);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    // ========== Pool Management ==========
    function createPool(address tokenA, address tokenB) external onlyOwner {
        require(tokenA != tokenB, "Same token");
        require(whitelisted[tokenA] && whitelisted[tokenB], "Token not whitelisted");

        bytes32 poolId = _getPoolId(tokenA, tokenB);
        require(!pools[poolId].exists, "Pool exists");

        pools[poolId] = Pool({
            reserveA: 0,
            reserveB: 0,
            totalLP: 0,
            exists: true
        });

        emit PoolCreated(poolId, tokenA, tokenB);
    }

    function whitelistToken(address token) external onlyOwner {
        whitelisted[token] = true;
    }

    // ========== Swap ==========
    function swap(address tokenIn, address tokenOut, uint256 amountIn) external returns (uint256 amountOut) {
        require(amountIn > 0, "Zero amount");
        require(whitelisted[tokenIn] && whitelisted[tokenOut], "Token not whitelisted");

        (address tokenA, address tokenB) = _sortTokens(tokenIn, tokenOut);
        bytes32 poolId = _getPoolId(tokenA, tokenB);
        Pool storage pool = pools[poolId];
        require(pool.exists, "Pool not found");

        uint256 reserveIn;
        uint256 reserveOut;
        if (tokenIn == tokenA) {
            reserveIn = pool.reserveA;
            reserveOut = pool.reserveB;
        } else {
            reserveIn = pool.reserveB;
            reserveOut = pool.reserveA;
        }

        require(reserveIn > 0 && reserveOut > 0, "Insufficient liquidity");

        // Calculate output: (amountIn * 997 * reserveOut) / (reserveIn * 10000 + amountIn * 997)
        uint256 amountInWithFee = amountIn * (FEE_DENOMINATOR - FEE_BPS);
        amountOut = (amountInWithFee * reserveOut) / (reserveIn * FEE_DENOMINATOR + amountInWithFee);
        require(amountOut > 0, "Insufficient output");

        // Transfer tokens
        require(IERC20(tokenIn).transferFrom(msg.sender, address(this), amountIn), "Transfer in failed");
        require(IERC20(tokenOut).transfer(msg.sender, amountOut), "Transfer out failed");

        // Update reserves
        if (tokenIn == tokenA) {
            pool.reserveA += amountIn;
            pool.reserveB -= amountOut;
        } else {
            pool.reserveB += amountIn;
            pool.reserveA -= amountOut;
        }

        emit Swap(msg.sender, tokenIn, tokenOut, amountIn, amountOut);
    }

    // ========== Add Liquidity ==========
    function addLiquidity(address tokenA, address tokenB, uint256 amountA, uint256 amountB) external returns (uint256 liquidity) {
        require(amountA > 0 && amountB > 0, "Zero amounts");

        bytes32 poolId = _getPoolId(tokenA, tokenB);
        Pool storage pool = pools[poolId];
        require(pool.exists, "Pool not found");

        // Calculate LP tokens
        if (pool.totalLP == 0) {
            liquidity = _sqrt(amountA * amountB);
        } else {
            uint256 liqA = (amountA * pool.totalLP) / pool.reserveA;
            uint256 liqB = (amountB * pool.totalLP) / pool.reserveB;
            liquidity = liqA < liqB ? liqA : liqB;
        }

        require(liquidity > 0, "Insufficient liquidity minted");

        // Transfer tokens in
        require(IERC20(tokenA).transferFrom(msg.sender, address(this), amountA), "Transfer A failed");
        require(IERC20(tokenB).transferFrom(msg.sender, address(this), amountB), "Transfer B failed");

        // Update state
        pool.reserveA += amountA;
        pool.reserveB += amountB;
        pool.totalLP += liquidity;
        lpBalances[poolId][msg.sender] += liquidity;

        emit LiquidityAdded(msg.sender, poolId, amountA, amountB, liquidity);
    }

    // ========== Remove Liquidity ==========
    function removeLiquidity(address tokenA, address tokenB, uint256 liquidity) external returns (uint256 amountA, uint256 amountB) {
        bytes32 poolId = _getPoolId(tokenA, tokenB);
        Pool storage pool = pools[poolId];
        require(pool.exists, "Pool not found");
        require(lpBalances[poolId][msg.sender] >= liquidity, "Insufficient LP balance");

        amountA = (liquidity * pool.reserveA) / pool.totalLP;
        amountB = (liquidity * pool.reserveB) / pool.totalLP;
        require(amountA > 0 && amountB > 0, "Insufficient liquidity burned");

        lpBalances[poolId][msg.sender] -= liquidity;
        pool.totalLP -= liquidity;
        pool.reserveA -= amountA;
        pool.reserveB -= amountB;

        require(IERC20(tokenA).transfer(msg.sender, amountA), "Transfer A failed");
        require(IERC20(tokenB).transfer(msg.sender, amountB), "Transfer B failed");

        emit LiquidityRemoved(msg.sender, poolId, amountA, amountB);
    }

    // ========== View Functions ==========
    function getAmountOut(address tokenIn, address tokenOut, uint256 amountIn) external view returns (uint256) {
        (address tokenA, address tokenB) = _sortTokens(tokenIn, tokenOut);
        bytes32 poolId = _getPoolId(tokenA, tokenB);
        Pool storage pool = pools[poolId];

        uint256 reserveIn = tokenIn == tokenA ? pool.reserveA : pool.reserveB;
        uint256 reserveOut = tokenIn == tokenA ? pool.reserveB : pool.reserveA;

        if (reserveIn == 0 || reserveOut == 0) return 0;

        uint256 amountInWithFee = amountIn * (FEE_DENOMINATOR - FEE_BPS);
        return (amountInWithFee * reserveOut) / (reserveIn * FEE_DENOMINATOR + amountInWithFee);
    }

    function getReserves(address tokenA, address tokenB) external view returns (uint256, uint256) {
        bytes32 poolId = _getPoolId(tokenA, tokenB);
        Pool storage pool = pools[poolId];
        return (pool.reserveA, pool.reserveB);
    }

    function getLPBalance(address tokenA, address tokenB, address user) external view returns (uint256) {
        bytes32 poolId = _getPoolId(tokenA, tokenB);
        return lpBalances[poolId][user];
    }

    // ========== Internal ==========
    function _getPoolId(address tokenA, address tokenB) internal pure returns (bytes32) {
        (address a, address b) = _sortTokens(tokenA, tokenB);
        return keccak256(abi.encodePacked(a, b));
    }

    function _sortTokens(address a, address b) internal pure returns (address, address) {
        return a < b ? (a, b) : (b, a);
    }

